  filter = "resource.type=\"gce_network\" AND (protoPayload.methodName:\"compute.networks.insert\" OR protoPayload.methodName:\"compute.networks.patch\" OR protoPayload.methodName:\"compute.networks.delete\" OR protoPayload.methodName:\"compute.networks.removePeering\" OR protoPayload.methodName:\"compute.networks.addPeering\")"
}

# Alert policy associated with the logs-based metric
resource "google_monitoring_alert_policy" "<example_resource_name>" {
  display_name = "<example_resource_name>"

  conditions {
    condition_threshold {
      # CRITICAL: Reference the logs-based metric so the policy is associated with it
      filter          = "metric.type=\"logging.googleapis.com/user/<example_resource_name>\""
      comparison      = "COMPARISON_GT"
      threshold_value = 0
      duration        = "0s"
    }
  }
}
```

