# Terraform: launch instance with trusted image certificates

# Note: Requires Glance image with signature metadata and Barbican certificate

resource "openstack_compute_instance_v2" "instance" {
  name            = "secure-instance"
  image_id        = var.signed_image_id  # Must be signed image
  flavor_id       = var.flavor_id
  key_pair        = var.key_pair_name
  security_groups = ["default"]

  # Specify trusted certificate IDs for signature validation
  # Note: This requires Nova microversion 2.63+ support
  trusted_image_certificates = [
    var.image_signing_cert_id,
    var.backup_cert_id
  ]

  network {
    name = var.network_name
  }
}

# Ensure image has signature metadata
data "openstack_images_image_v2" "signed_image" {
  name        = "ubuntu-22.04-signed"
  most_recent = true

  # Verify signature properties exist
  properties = {
    img_signature                   = "required"
    img_signature_hash_method       = "SHA-256"
    img_signature_key_type          = "RSA-PSS"
    img_signature_certificate_uuid  = "required"
  }
}
```

