# Enable VCN flow logs (covers all subnets in the VCN)
resource "oci_logging_log" "<example_resource_name>" {
  display_name = "<example_resource_name>"
  log_group_id = "<example_resource_id>"          # Existing Log Group OCID
  log_type     = "SERVICE"
  is_enabled   = true

  configuration {
    source {
      source_type = "OCISERVICE"
      service     = "flowlogs"                     # CRITICAL: enables VCN/Subnet flow logging
      resource    = "<example_resource_id>"       # CRITICAL: VCN OCID (use subnet OCID if enabling per-subnet)
      category    = "vcn"                          # CRITICAL: set to "vcn" (or "subnet" for subnet-level)
      parameters  = { capture_filter = "<example_resource_id>" }  # Capture Filter OCID
    }
  }
}
```

